function changePrice(a){$.getJSON("https://cdn.shirai-store.net/assets/json/feature/"+a+"_v1_0.json",function(a){$(".changePrice").each(function(){var e,n=$(this).data("products"),i=a.find(a=>a.productUrl===n);if(i){var c=i.sellingPrice,s=i.normalPrice;e=c<s?'<span class="mark-sale">SALE</span><span class="normalPrice">¥'+s.toLocaleString()+'（税込）</span><span class="sellingPrice salePrice">¥'+c.toLocaleString()+"（税込）</span>":'<span class="sellingPrice">¥'+c.toLocaleString()+"（税込）</span>",$(this).html(e)}})})}$(function(){var a=location.href;a.indexOf("/magazine/school-bag")>-1?changePrice("magazine-school-bag"):a.indexOf("/magazine/cabinet-stylish")>-1?changePrice("cabinet-stylish"):a.indexOf("/magazine/chest-stylish")>-1?changePrice("chest-stylish"):a.indexOf("/magazine/compact-tvboard")>-1?changePrice("compact-tvboard"):a.indexOf("/magazine/kitchen-strage-stylish")>-1?changePrice("kitchen-strage-stylish"):a.indexOf("/magazine/newLife")>-1&&changePrice("magazine-newLife")});